if (cacheParams.prefetch.isEmpty) {
  val tlProbeFire = issueArb.io.out.fire
  val tlGrantPendingSameBlock = Cat(io.grantStatus.map(s =>
    s.valid && s.set === issueArb.io.out.bits.set && s.tag === issueArb.io.out.bits.tag
  )).orR
  chisel3.util.experimental.BoringUtils.addSource(tlGrantPendingSameBlock, s"${cacheParams.name}_{{source_label}}_grant_pending", disableDedup = true)
  chisel3.util.experimental.BoringUtils.addSource(tlProbeFire, s"${cacheParams.name}_{{source_label}}_probe_fire", disableDedup = true)
}
